// Package models provides the data structures for IDSEC Identity federation operations.
package models

// IdsecIdentityCreateFederation is the write model for the create operation.
//
// The OIDC fields carry no default tag on purpose: a default would also apply to SAML
// federations, which read those fields back empty and would drift forever. The service fills the
// OIDC defaults (grant type AuthorizationCode, PKCE on) only when FederationType is OIDC.
type IdsecIdentityCreateFederation struct {
	FederationName           string                                    `json:"federation_name" mapstructure:"federation_name" flag:"federation-name" desc:"The display name of the external identity provider." validate:"required"`
	FederationType           string                                    `json:"federation_type" mapstructure:"federation_type" flag:"federation-type" desc:"The federation protocol." validate:"required" choices:"SAML 2.0,OIDC"`
	Active                   bool                                      `json:"active" mapstructure:"active" flag:"active" desc:"Whether the federation is active." default:"true"`
	Domains                  []string                                  `json:"domains,omitempty" mapstructure:"domains" flag:"domains" desc:"The federated domains routed to this identity provider."`
	OIDCMetadataURL          string                                    `json:"oidc_metadata_url,omitempty" mapstructure:"oidc_metadata_url" flag:"oidc-metadata-url" desc:"The full OIDC discovery document URL, ending in /.well-known/openid-configuration. Required for OIDC." validate:"required_if=FederationType OIDC,excluded_unless=FederationType OIDC,regexp=\\.well-known/openid-(configuration0x7Cfederation)/?$"`
	OIDCClientID             string                                    `json:"oidc_client_id,omitempty" mapstructure:"oidc_client_id" flag:"oidc-client-id" desc:"The client ID registered at the OIDC identity provider. Required for OIDC." validate:"required_if=FederationType OIDC,excluded_unless=FederationType OIDC"`
	OIDCClientSecret         *string                                   `json:"oidc_client_secret,omitempty" mapstructure:"oidc_client_secret" flag:"oidc-client-secret" desc:"The client secret registered at the OIDC identity provider. Required for OIDC." secret:"true" validate:"excluded_unless=FederationType OIDC"`
	OIDCGrantType            string                                    `json:"oidc_grant_type,omitempty" mapstructure:"oidc_grant_type" flag:"oidc-grant-type" desc:"The OIDC grant type. Defaults to AuthorizationCode for OIDC." choices:"AuthorizationCode" validate:"excluded_unless=FederationType OIDC"`
	PKCEEnabled              *bool                                     `json:"oidc_pkce_enabled,omitempty" mapstructure:"oidc_pkce_enabled" flag:"oidc-pkce-enabled" desc:"Whether PKCE is used. Defaults to true for OIDC." validate:"excluded_unless=FederationType OIDC"`
	OIDCScopes               []string                                  `json:"oidc_scopes,omitempty" mapstructure:"oidc_scopes" flag:"oidc-scopes" desc:"The scopes requested from the OIDC identity provider." validate:"excluded_unless=FederationType OIDC"`
	LogoutCallBackURI        string                                    `json:"oidc_post_logout_redirect_uri,omitempty" mapstructure:"oidc_post_logout_redirect_uri" flag:"oidc-post-logout-redirect-uri" desc:"The post logout redirect URI." validate:"excluded_unless=FederationType OIDC"`
	GroupMappings            []IdsecIdentityFederationGroupMapping     `json:"group_mappings,omitempty" mapstructure:"group_mappings" flag:"group-mappings" desc:"The identity provider group assertions mapped to federated groups, in order." validate:"dive"`
	MapUsers                 string                                    `json:"map_users,omitempty" mapstructure:"map_users" flag:"map-users" desc:"Whether federated users are linked to existing directory users." choices:"Disabled,Optional,Required"`
	MapUserAttribute         string                                    `json:"map_user_attribute,omitempty" mapstructure:"map_user_attribute" flag:"map-user-attribute" desc:"The identity provider attribute used to find the directory user."`
	MapUserDirectoryService  string                                    `json:"map_user_directory_service,omitempty" mapstructure:"map_user_directory_service" flag:"map-user-directory-service" desc:"The directory service UUID searched for the user. Empty means any directory service."`
	MapUserBy                string                                    `json:"map_user_by,omitempty" mapstructure:"map_user_by" flag:"map-user-by" desc:"The directory user attribute matched against map_user_attribute."`
	MapUserSyncWithCloudUser *bool                                     `json:"map_user_sync_with_cloud_user,omitempty" mapstructure:"map_user_sync_with_cloud_user" flag:"map-user-sync-with-cloud-user" desc:"Whether the directory user is updated from the identity provider attributes."`
	MapUserSyncWithFedUser   *bool                                     `json:"map_user_sync_with_federated_user,omitempty" mapstructure:"map_user_sync_with_federated_user" flag:"map-user-sync-with-federated-user" desc:"Whether the federated user is updated from the identity provider attributes."`
	MapUserUsesGroups        *bool                                     `json:"map_user_uses_groups,omitempty" mapstructure:"map_user_uses_groups" flag:"map-user-uses-groups" desc:"Whether the mapped user also receives the federated group memberships."`
	MapUserAllowFederations  *bool                                     `json:"map_user_allow_other_federations,omitempty" mapstructure:"map_user_allow_other_federations" flag:"map-user-allow-other-federations" desc:"Whether the federated user may map to a user that belongs to another federation."`
	MapUserCreateIfNotFound  *bool                                     `json:"map_user_create_if_not_found,omitempty" mapstructure:"map_user_create_if_not_found" flag:"map-user-create-if-not-found" desc:"Whether a Cloud Directory user is created when none is found. Requires map_users Required."`
	AttributeMappings        []IdsecIdentityFederationAttributeMapping `json:"attribute_mappings,omitempty" mapstructure:"attribute_mappings" flag:"attribute-mappings" desc:"Identity provider attributes copied onto Cloud Directory user attributes. Stored only when map_user_directory_service is the Cloud Directory and a sync or create option is on." validate:"dive"`
	DeviceTypes              []string                                  `json:"device_types,omitempty" mapstructure:"device_types" flag:"device-types" desc:"The device types routed to this identity provider. Empty means every device type. A partial selection requires map_users Required." choices:"Android,iOS,Others" validate:"max=2"`
	UserAgents               []string                                  `json:"user_agents,omitempty" mapstructure:"user_agents" flag:"user-agents" desc:"The client types routed to this identity provider." choices:"Browser,NonBrowser,Any"`
	SAMLMetadataURL          string                                    `json:"saml_metadata_url,omitempty" mapstructure:"saml_metadata_url" flag:"saml-metadata-url" desc:"The SAML identity provider metadata URL. The server fetches the metadata on every create and update." validate:"excluded_if=FederationType OIDC,excluded_with=SAMLMetadataXML SAMLSignInURL SAMLLogoutURL SAMLSigningCertificate"`
	SAMLSignInURL            string                                    `json:"saml_sign_in_url,omitempty" mapstructure:"saml_sign_in_url" flag:"saml-sign-in-url" desc:"The SAML identity provider sign-in URL. Read from the metadata when it is supplied." validate:"excluded_if=FederationType OIDC,required_with=SAMLLogoutURL SAMLSigningCertificate"`
	SAMLLogoutURL            string                                    `json:"saml_logout_url,omitempty" mapstructure:"saml_logout_url" flag:"saml-logout-url" desc:"The SAML identity provider logout URL. Read from the metadata when it is supplied." validate:"excluded_if=FederationType OIDC"`
	SAMLSignAlgorithm        string                                    `json:"saml_sign_algorithm,omitempty" mapstructure:"saml_sign_algorithm" flag:"saml-sign-algorithm" desc:"The algorithm the SAML authentication request is signed with." choices:"SHA1,SHA256" validate:"excluded_if=FederationType OIDC"`
	SAMLURLRedirectEnabled   *bool                                     `json:"saml_url_redirect_enabled,omitempty" mapstructure:"saml_url_redirect_enabled" flag:"saml-url-redirect-enabled" desc:"Whether users are redirected to a URL that matches saml_url_redirect_pattern after SAML sign-in." validate:"excluded_if=FederationType OIDC"`
	SAMLURLRedirectPattern   string                                    `json:"saml_url_redirect_pattern,omitempty" mapstructure:"saml_url_redirect_pattern" flag:"saml-url-redirect-pattern" desc:"The https URL pattern, which may contain *, that redirection after SAML sign-in is allowed to." validate:"excluded_if=FederationType OIDC"`
	SAMLOAuthClientID        string                                    `json:"saml_oauth_client_id,omitempty" mapstructure:"saml_oauth_client_id" flag:"saml-oauth-client-id" desc:"The OAuth client ID the tenant uses to sign the identity provider's users in with a password, through saml_oauth_access_token_url." validate:"excluded_if=FederationType OIDC"`
	SAMLOAuthClientSecret    *string                                   `json:"saml_oauth_client_secret,omitempty" mapstructure:"saml_oauth_client_secret" flag:"saml-oauth-client-secret" desc:"The OAuth client secret for saml_oauth_client_id. The server keeps the stored secret when none is sent." secret:"true" validate:"excluded_if=FederationType OIDC"`
	SAMLOAuthAccessTokenURL  string                                    `json:"saml_oauth_access_token_url,omitempty" mapstructure:"saml_oauth_access_token_url" flag:"saml-oauth-access-token-url" desc:"The identity provider's OAuth token URL, used for password sign-in. Must be an https URL." validate:"excluded_if=FederationType OIDC,regexp=(?i)^https://"`
	SAMLMetadataXML          *string                                   `json:"saml_metadata_xml,omitempty" mapstructure:"saml_metadata_xml" flag:"saml-metadata-xml" desc:"The SAML identity provider metadata document, uploaded instead of fetching it from saml_metadata_url." validate:"excluded_if=FederationType OIDC,excluded_with=SAMLSignInURL SAMLLogoutURL SAMLSigningCertificate"`
	SAMLSigningCertificate   *string                                   `json:"saml_signing_certificate,omitempty" mapstructure:"saml_signing_certificate" flag:"saml-signing-certificate" desc:"The SAML identity provider signing certificate, PEM or base64 encoded, for a federation configured without metadata." validate:"excluded_if=FederationType OIDC"`
}
